DROP TABLE if exists prov_table_list;
CREATE TABLE 
    IF NOT EXISTS prov_table_list 
    ( 
        table_seq           INTEGER, 
        table_name          VARCHAR, 
        table_comment       VARCHAR, 
        timeliness_type     VARCHAR, 
        timeliness_comment  VARCHAR, 
        national_flag       INTEGER, 
        pingan_flag         INTEGER, 
        early_warning       INTEGER, 
        emergency_warning   INTEGER, 
        medicine_regulatory INTEGER, 
        quality_flag        INTEGER 
    );
COMMENT ON COLUMN prov_table_list.table_seq IS '表序号';
COMMENT ON COLUMN prov_table_list.table_name IS '表名称';
COMMENT ON COLUMN prov_table_list.table_comment IS '表注释';
COMMENT ON COLUMN prov_table_list.timeliness_type IS '时效性类别，0：实时表；1：2小时内；2：T+0';
COMMENT ON COLUMN prov_table_list.timeliness_comment IS '时效性注释';
COMMENT ON COLUMN prov_table_list.national_flag IS '国标表标志';
COMMENT ON COLUMN prov_table_list.pingan_flag IS '平安表标志';
COMMENT ON COLUMN prov_table_list.early_warning IS '预警处标志';
COMMENT ON COLUMN prov_table_list.emergency_warning IS '应急处标志';
COMMENT ON COLUMN prov_table_list.medicine_regulatory IS '药政处标志';


drop table if exists org_list;
CREATE TABLE 
    IF NOT EXISTS org_list 
    ( 
        city             VARCHAR, 
        "区县"             VARCHAR, 
        org_code         VARCHAR, 
        org_name         VARCHAR, 
        "责任公司"           VARCHAR, 
        station_hospital VARCHAR, 
        is_516_flag      VARCHAR, 
        "是否民营109"        VARCHAR, 
        "is_412名单"       VARCHAR, 
        "是否分院区"          VARCHAR, 
        "是否基层"           VARCHAR, 
        "is_412合计"       VARCHAR, 
        "是否26"           VARCHAR, 
        "版本"             VARCHAR, 
        "专网IP"           VARCHAR, 
        "专网端口"           VARCHAR, 
        "测试结果"           VARCHAR, 
        "是否满足实时要求"       VARCHAR, 
        "有无数据"           VARCHAR, 
        "近期有无数据"         VARCHAR, 
        "已推送平安"          VARCHAR, 
        "时效性是否达标"        VARCHAR, 
        "是否主院区"          VARCHAR, 
        "共用机构等备注"        VARCHAR, 
        "组别"             VARCHAR 
    );

COMMENT ON table org_list is '质控机构列表'; 
COMMENT ON column org_list.city is '地市(州)'; 
COMMENT ON column org_list.org_code is '机构编码';   
COMMENT ON column org_list.org_name is '机构名称'; 
COMMENT ON column org_list.is_516_flag is '是否516标志';


